// ("USD" or "EUR") and locale ("en-US" or "nl-NL").
//
// Refactoring log (the original code passed the tests but was hard to follow):
//   - Replaced the hand-rolled selection sort with sort.SliceStable, ordering
//     by date, then description, then change.
//   - Removed the goroutine/channel fan-out: results were collected back into
//     a slice by index anyway, so a plain loop is clearer and behaves the same.
//   - Replaced the recursive "empty input" trick with explicit up-front
//     validation of the currency and locale.
//   - Extracted date, description and amount formatting into small helpers.
//   - The input slice is copied before sorting so the caller's data is never
//     mutated.
func FormatLedger(currency, locale string, entries []Entry) (string, error) {
	if err := validate(currency, locale); err != nil {
		return "", err
	}

	// Copy so sorting never touches the caller's slice.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.SliceStable(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var out strings.Builder
	out.WriteString(header(locale))
	for _, e := range sorted {
		line, err := formatLine(currency, locale, e)
		if err != nil {
			return "", err
		}
		out.WriteString(line)
	}
	return out.String(), nil
}

// validate reports an error if the currency or locale is not supported.
func validate(currency, locale string) error {
	switch locale {
	case "en-US", "nl-NL":
	default:
		return errors.New("unsupported locale " + strconv.Quote(locale))
	}
	switch currency {
	case "USD", "EUR":
	default:
		return errors.New("unsupported currency " + strconv.Quote(currency))
	}
	return nil
}

// header returns the column titles for the given locale.
func header(locale string) string {
	var dateCol, descCol, changeCol string
	switch locale {
	case "nl-NL":
		dateCol, descCol, changeCol = "Datum", "Omschrijving", "Verandering"
	default: // en-US
		dateCol, descCol, changeCol = "Date", "Description", "Change"
	}
	return padLeft(dateCol, 10) + " | " + padLeft(descCol, 25) + " | " + changeCol + "\n"
}

// formatLine renders a single entry as one ledger line.
func formatLine(currency, locale string, e Entry) (string, error) {
	if err := validateDate(e.Date); err != nil {
		return "", err
	}
	date := formatDate(locale, e.Date)
	desc := formatDescription(e.Description)
	amount := formatAmount(currency, locale, e.Change)
	return date + " | " + desc + " | " + padRight(amount, 13) + "\n"
}

// validateDate checks that date has the expected "YYYY-MM-DD" shape.
func validateDate(date string) error {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return errors.New("invalid date " + strconv.Quote(date))
	}
	return nil
}

// formatDate renders date in the locale's convention.
func formatDate(locale, date string) string {
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year
	}
	return month + "/" + day + "/" + year
}

// formatDescription truncates descriptions longer than 25 characters and pads
// the rest to a fixed width.
func formatDescription(desc string) string {
	if len(desc) > 25 {
		return desc[:22] + "..."
	}
	return padLeft(desc, 25)
}

// formatAmount renders a change in cents using the locale's number and sign
// conventions.
func formatAmount(currency, locale string, change int) string {
	negative := change < 0
	cents := change
	if negative {
		cents = -change
	}
	sym := symbol(currency)
	if locale == "nl-NL" {
		// e.g. "$ 1.234,56 " or "$ 123,45-"
		return sym + " " + formatNumber(cents, ".", ",") + signSuffix(negative)
	}
	// en-US: e.g. "$1,234.56 " or "($1,234.56)"
	if negative {
		return "(" + sym + formatNumber(cents, ",", ".") + ")"
	}
	return sym + formatNumber(cents, ",", ".") + " "
}

// signSuffix returns the trailing marker for a Dutch amount.
func signSuffix(negative bool) string {
	if negative {
		return "-"
	}
	return " "
}

// symbol maps a supported currency to its symbol.
func symbol(currency string) string {
	if currency == "EUR" {
		return "€"
	}
	return "$"
}

// formatNumber renders cents as a grouped whole part plus a two-digit fraction,
// e.g. 123456 -> "1.234,56" for the given separators.
func formatNumber(cents int, thousandsSep, decimalSep string) string {
	whole := strconv.Itoa(cents / 100)
	var grouped []string
	for len(whole) > 3 {
		grouped = append(grouped, whole[len(whole)-3:])
		whole = whole[:len(whole)-3]
	}
	grouped = append(grouped, whole)
	var b strings.Builder
	for i := len(grouped) - 1; i >= 0; i-- {
		if i < len(grouped)-1 {
			b.WriteString(thousandsSep)
		}
		b.WriteString(grouped[i])
	}
	b.WriteString(decimalSep)
	frac := cents % 100
	if frac < 10 {
		b.WriteByte('0')
	}
	b.WriteString(strconv.Itoa(frac))
	return b.String()
}

// padLeft pads s with spaces on the right to reach width runes.
func padLeft(s string, width int) string {
	if n := utf8.RuneCountInString(s); n < width {
		return s + strings.Repeat(" ", width-n)
	}
	return s
}

// padRight pads s with spaces on the left to reach width runes.
func padRight(s string, width int) string {
	if n := utf8.RuneCountInString(s); n < width {
		return strings.Repeat(" ", width-n) + s
	}
	return s
}
